  Button Button(string text,Action action){var b=ReferencePage.Button(text,action);b.Padding=new Thickness(10,5,10,5);b.Margin=new Thickness(2,0,2,0);b.MinHeight=30;b.SetResourceReference(Control.BorderBrushProperty,"Border");return b;}
  void AddTool(Panel panel,string kind,string label,string tip){var button=Button(label,()=>Mode(kind));button.Name="CanvasTool_"+kind;button.ToolTip=tip;System.Windows.Automation.AutomationProperties.SetName(button,label);toolButtons.Add(kind,button);panel.Children.Add(button);}
  void InstallDrawingStyle(Panel panel){
   inkColors=new ComboBox{Name="CanvasInkColor",Width=100,Margin=new Thickness(2,0,4,0),ToolTip="新标注颜色；自动色随浅色和深色主题保持清晰"};System.Windows.Automation.AutomationProperties.SetName(inkColors,"新标注颜色");
   foreach(var pair in new[]{Tuple.Create("auto","自动"),Tuple.Create("#333333","深灰"),Tuple.Create("#F5F5F5","白色"),Tuple.Create("#C45B61","红色"),Tuple.Create("#B38A3D","金色"),Tuple.Create("#4C9277","绿色"),Tuple.Create("#547FC3","蓝色"),Tuple.Create("#8266BD","紫色")}){
    var row=new StackPanel{Orientation=Orientation.Horizontal};var sample=new Border{Width=11,Height=11,CornerRadius=new CornerRadius(5.5),Margin=new Thickness(0,0,7,0),VerticalAlignment=VerticalAlignment.Center};if(pair.Item1=="auto")sample.SetResourceReference(Border.BackgroundProperty,"Text");else sample.Background=(Brush)new BrushConverter().ConvertFromString(pair.Item1);row.Children.Add(sample);row.Children.Add(new TextBlock{Text=pair.Item2});inkColors.Items.Add(new ComboBoxItem{Content=row,Tag=pair.Item1,ToolTip=pair.Item2});
   }inkColors.SelectedIndex=0;inkColors.SelectionChanged+=(s,e)=>{var choice=inkColors.SelectedItem as ComboBoxItem;if(choice!=null)drawingColor=(string)choice.Tag;};panel.Children.Add(inkColors);
   strokeWidths=new ComboBox{Name="CanvasStrokeWidth",Width=78,Margin=new Thickness(2,0,2,0),ToolTip="新笔画粗细；以当前缩放下的像素为准"};System.Windows.Automation.AutomationProperties.SetName(strokeWidths,"新笔画粗细");foreach(double width in new[]{1.0,2.0,3.0,5.0,8.0,12.0})strokeWidths.Items.Add(new ComboBoxItem{Content=width.ToString(CultureInfo.InvariantCulture)+" px",Tag=width});strokeWidths.SelectedIndex=1;strokeWidths.SelectionChanged+=(s,e)=>{var choice=strokeWidths.SelectedItem as ComboBoxItem;if(choice!=null)drawingWidth=(double)choice.Tag;};panel.Children.Add(strokeWidths);
